const PF_FIL_PREFIXES = ['gi', 'gina', 'gipa', 'ga', 'na', 'nag', 'naga', 'nagka', 'naka', 'nakaka', 'nang', 'nan',
  'ni', 'ma', 'mag', 'maga', 'magka', 'maka', 'mang', 'man', 'mi', 'pa', 'pag', 'pang', 'paka', 'ka', 'kina',
  'i', 'ipa', 'in', 'um', 'nakig', 'makig', 'pakig'];
const PF_FIL_SUFFIXES = ['an', 'han', 'on', 'hon', 'a', 'ha', 'ay', 'in', 'hin', 'ero', 'era', 'eros', 'eras'];
const PF_EN_PREFIXES = ['mother', 'motha', 'mutha', 'muther', 'mada'];
const PF_EN_SUFFIXES = ['s', 'ing', 'in', 'ed', 'er', 'ers', 'face', 'head'];
const PF_WS = ' \\t\\n\\r\\f\\v\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF';
const PF_WORDCH = 'A-Za-z0-9\\u00C0-\\u024F\\u1E00-\\u1EFF@$';
const PF_DELIM_RE = new RegExp('([' + PF_WS + ',;:/\\\\()\\[\\]{}"\\u201C\\u201D\\u00AB\\u00BB<>?]+)');
const PF_LEAD_RE = new RegExp('^[^' + PF_WORDCH + ']*');
const PF_TRAIL_RE = new RegExp('[^' + PF_WORDCH + ']*$');
const PF_ONLY_WS_RE = new RegExp('^[' + PF_WS + ']+$');
const PF_NON_WS_RE = new RegExp('[^' + PF_WS + ']', 'gu');
const PF_SEP_RE = /[.\-_'‘’`]/;
const PF_PART_RE = /[^.\-_'‘’`]+/g;
const PF_MAX_TOKEN = 64;
const PF_MAX_RUN = 20;
function pfLetters(word) {
  return Array.from(word).map((ch) => (PF_CLASS[ch] ? '[' + PF_CLASS[ch] + ']' : ch) + '+').join('');
}
function pfAlt(list) {
  return '(?:' + list.map(pfLetters).join('|') + ')';
}
function pfFilRoot(word) {
  if (/^[aeiou]/.test(word)) return pfLetters(word);
  const withInfix = (w) => pfLetters(w[0]) + '(?:in|um)?' + pfLetters(w.slice(1));
  const syl = (word.match(/^[^aeiou]+[aeiou]+/) || [word[0]])[0];
  return '(?:' + withInfix(syl) + ')?' + withInfix(word);
}
function pfPatterns(groups) {
  const roots = { fil: [], en: [], none: [] };
  for (const [group, affix, ...words] of PROFANITY_WORDS) {
    if (groups[group]) for (const w of words) roots[affix].push(affix === 'fil' ? pfFilRoot(w) : pfLetters(w));
  }
  const alts = [];
  if (roots.fil.length) alts.push(pfAlt(PF_FIL_PREFIXES) + '?(?:' + roots.fil.join('|') + ')' + pfAlt(PF_FIL_SUFFIXES) + '?');
  if (roots.en.length) alts.push(pfAlt(PF_EN_PREFIXES) + '?(?:' + roots.en.join('|') + ')' + pfAlt(PF_EN_SUFFIXES) + '?');
  if (roots.none.length) alts.push('(?:' + roots.none.join('|') + ')');
  return {
    token: alts.length ? '^(?:' + alts.join('|') + ')$' : '^(?!)$',
    phrases: PROFANITY_PHRASES.filter(([g]) => groups[g]).map(([, a, b]) => ['^' + pfLetters(a) + '$', '^' + pfLetters(b) + '$']),
  };
}
const PF_PATTERNS = pfPatterns(PROFANITY_GROUPS);
const PF_TOKEN_RE = new RegExp(PF_PATTERNS.token);
const PF_PHRASE_RES = PF_PATTERNS.phrases.map(([a, b]) => [new RegExp(a), new RegExp(b)]);
function pfNorm(s) {
  return String(s).normalize('NFD').toLowerCase().replace(/[̀-ͯ.\-_'‘’`]/g, '');
}
function pfIsWord(core) {
  return core.length <= PF_MAX_TOKEN && PF_TOKEN_RE.test(pfNorm(core));
}
function pfMaskSpan(s) {
  return String(s).replace(PF_NON_WS_RE, '*');
}
function findProfanity(text) {
  if (typeof text !== 'string' || !text) return [];
  const pieces = text.split(PF_DELIM_RE);   // even = word chunk, odd = delimiters
  const chunks = [];
  let pos = 0;
  for (let i = 0; i < pieces.length; i++) {
    const p = pieces[i];
    if (i % 2 === 0 && p) {
      const lead = PF_LEAD_RE.exec(p)[0].length;
      const core = p.slice(lead, p.length - PF_TRAIL_RE.exec(p.slice(lead))[0].length);
      chunks.push({ start: pos + lead, core, after: pieces[i + 1] || '', masked: false });
    }
    pos += p.length;
  }
  const spans = [];
  const add = (start, end) => spans.push({ start, end });
  for (const c of chunks) {
    if (!c.core) continue;
    if (pfIsWord(c.core)) { add(c.start, c.start + c.core.length); c.masked = true; continue; }
    if (!PF_SEP_RE.test(c.core)) continue;
    PF_PART_RE.lastIndex = 0;
    let m;
    while ((m = PF_PART_RE.exec(c.core))) {
      if (pfIsWord(m[0])) { add(c.start + m.index, c.start + m.index + m[0].length); c.masked = true; }
    }
  }
  const single = (c) => !c.masked && Array.from(c.core).length === 1;
  for (let k = 0; k < chunks.length;) {
    if (!single(chunks[k])) { k++; continue; }
    let e = k;
    while (e + 1 < chunks.length && single(chunks[e + 1]) && PF_ONLY_WS_RE.test(chunks[e].after)) e++;
    for (let s = k; s <= e;) {
      let len = Math.min(e - s + 1, PF_MAX_RUN);
      for (; len >= 3; len--) {
        if (pfIsWord(chunks.slice(s, s + len).map((c) => c.core).join(''))) break;
      }
      if (len >= 3) {
        const last = chunks[s + len - 1];
        add(chunks[s].start, last.start + last.core.length);
        for (let j = s; j < s + len; j++) chunks[j].masked = true;
        s += len;
      } else {
        s++;
      }
    }
    k = e + 1;
  }
  for (let k = 0; k + 1 < chunks.length; k++) {
    const a = chunks[k];
    const b = chunks[k + 1];
    if (a.masked || b.masked || !a.core || !b.core || !PF_ONLY_WS_RE.test(a.after)) continue;
    const na = pfNorm(a.core);
    const nb = pfNorm(b.core);
    if (PF_PHRASE_RES.some(([ra, rb]) => ra.test(na) && rb.test(nb))) {
      add(a.start, b.start + b.core.length);
      a.masked = true;
      b.masked = true;
      k++;
    }
  }
  spans.sort((x, y) => x.start - y.start);
  return spans.map((s) => ({ start: s.start, end: s.end, text: text.slice(s.start, s.end) }));
}
function maskProfanity(text) {
  if (typeof text !== 'string' || !text) return text;
  const spans = findProfanity(text);
  if (!spans.length) return text;
  let out = '';
  let pos = 0;
  for (const s of spans) {
    out += text.slice(pos, s.start) + pfMaskSpan(s.text);
    pos = s.end;
  }
  return out + text.slice(pos);
}
function profaneKeyword(word) {
  return typeof word === 'string' && (word.includes('*') || maskProfanity(word) !== word);
}
// end of sexual-word filter

// Safely attempt to get the staff ID by checking nodes independently
let staffId = null;
let isManuallyCorrected = false; // New flag to track if this was manually corrected

// Attempt 1: 'clean data' node
try {
  const cleanDataNode = $('clean data1').first();
  if (cleanDataNode && cleanDataNode.json.staff_id) {
    staffId = cleanDataNode.json.staff_id;
  }
} catch (error) {
  // Node didn't run or data is missing, move on
}

// Attempt 2: 'SAST image from phone' node
if (!staffId) {
  try {
    const phoneNode = $('SAST image from phone').first();
    if (phoneNode && phoneNode.json.body && phoneNode.json.body.user_id) {
      staffId = phoneNode.json.body.user_id;
    }
  } catch (error) {
    // Node didn't run or data is missing
  }
}

// Attempt 2b: 'SAST from Website' node
if (!staffId) {
  try {
    const webNode = $('SAST from Website').first();
    if (webNode && webNode.json.body && webNode.json.body.staff_id) {
      staffId = webNode.json.body.staff_id;
    }
  } catch (error) {
    // Not a website execution
  }
}

// Attempt 3: 'sast-manual-correction' node
try {
  const manualNode = $('sast-manual-correction1').first();
  if (manualNode) {
    // If this node executed without throwing an error, we know it's a manual correction!
    isManuallyCorrected = true; 

    // Check for the user_id in the manual correction payload if we don't have a staffId yet
    if (!staffId && manualNode.json.body && manualNode.json.body.user_id) {
      staffId = manualNode.json.body.user_id;
    }
  }
} catch (error) {
  // Node didn't run, meaning this is an automated run
}

// website rows are already stored, so skip the shared upsert
let websiteRawStored = false;
try {
  const w = $('Website Raw Upsert').first();
  websiteRawStored = !!(w && w.json && w.json.saved === true);
} catch (error) {
  // Not a website execution
}

// stamp rule (2026-10-16): a valid stamp (3..12 digits, as printed) + its source, else NULL + NULL
function stampColumns(r) {
  const s = (typeof r['stamp_no'] === 'string' || typeof r['stamp_no'] === 'number') ? String(r['stamp_no']).trim() : '';
  const ok = /^[0-9]{3,12}$/.test(s);
  const src = ['gemini+python', 'gemini', 'staff', 'override'].includes(r['stamp_source']) ? r['stamp_source'] : 'staff';
  return { stamp_no: ok ? s : null, stamp_source: ok ? src : null };
}

// Map the raw data and include the new database flags
const rawData = $input.all().map(item => {
  const r = item.json;
  return {
    json: {
      instructor_ID: r['instructor_ID'] || null,
      subject_id: r['true_subject_id'] || null,
      term_id: r['current_term_id'] || null,
      // blank student id -> NULL so it never matches another row
      student_id: (typeof r['Student ID'] === 'string' ? r['Student ID'].trim() : r['Student ID']) || null,
      instructor: r['Instructor/Professor'] || null,

      m1: rating(r['M1']),
      m2: rating(r['M2']),
      m3: rating(r['M3']),
      m4: rating(r['M4']),
      m5: rating(r['M5']),
      m6: rating(r['M6']),
      m7: rating(r['M7']),
      m8: rating(r['M8']),
      m9: rating(r['M9']),
      m10: rating(r['M10']),

      p1: rating(r['P1']),
      p2: rating(r['P2']),
      p3: rating(r['P3']),
      p4: rating(r['P4']),
      p5: rating(r['P5']),
      p6: rating(r['P6']),
      p7: rating(r['P7']),
      p8: rating(r['P8']),
      p9: rating(r['P9']),
      p10: rating(r['P10']),

      // mask sexual words before storing
      Remarks_and_Suggestions: maskProfanity(cleanRemark(r['Remarks & Suggestions']) || '') || null,

      submitted_date: r['Date'] ? new Date(r['Date']).toISOString().split('T')[0] : null,

      sao_staff_id: staffId,

      // ADDED: Map to the columns shown in your Supabase screenshot
      manually_corrected: isManuallyCorrected,
      validation_status: isManuallyCorrected ? 'corrected' : 'auto',

      // only when present, so sheet imports never clear task_id
      ...(r['task_id'] && !Array.isArray(r['task_id']) ? { task_id: String(r['task_id']) } : {}),
      // stamp only when the mapper sent one, so sheet rows never clear it
      ...(Object.prototype.hasOwnProperty.call(r, 'stamp_no') ? stampColumns(r) : {}),
      ...(websiteRawStored ? { _raw_already_stored: true } : {})
    }
  };
});

const uniqueData = [];
const seen = new Set();

// Loop backwards to keep the newest submission and discard older duplicates
for (let i = rawData.length - 1; i >= 0; i--) {
  const item = rawData[i];
  const j = item.json;

  // The magic fingerprint checking Student + Instructor + Subject + Term
  const uniqueKey = `${j.student_id}_${j.instructor_ID}_${j.subject_id}_${j.term_id}`;

  // rows without a student id are never deduped
  if (j.student_id === null || !seen.has(uniqueKey)) {
    seen.add(uniqueKey);
    uniqueData.push(item);
  }
}

return uniqueData.reverse();

// Grab ALL 205 items from the If node
const allItems = $('If1').all();
const uniquePairs = {};

// Loop through all of them and find every unique Instructor + Term combo
for (const item of allItems) {
  const instId = item.json.instructor_ID;
  const termId = item.json.current_term_id;

  if (instId && termId) {
    uniquePairs[`${instId}_${termId}`] = {
      instructor_id: instId,
      term_id: termId
    };
  }
}

// Return the full list of unique instructors so Postgres updates ALL of them
return Object.values(uniquePairs).map(pair => ({ json: pair }));

const items = $input.all();

return items.map(item => {
  // n8n Webhook data is usually inside item.json.body
  const payload = item.json.body || item.json;

  const staffId = payload.user_id;
  const googleLink = payload.link;
  let sheetId = '';

  if (googleLink && typeof googleLink === 'string') {
    const match = googleLink.match(/\/d\/(.*?)(\/|$)/);
    if (match && match[1]) {
      sheetId = match[1];
    }
  }

  return {
    json: {
      staff_id: staffId,
      google_link: googleLink,
      sheetId: sheetId,  // Changed this so the Google Node recognizes it automatically!
      import_type: payload.type,
      sync_time: payload.timestamp
    }
  };
});

// SAST rating, from website_src/rating.js
function rating(v) {
  if (typeof v === 'string') v = v.trim();
  else if (typeof v !== 'number') return null;
  if (v === '') return null;
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= 5 ? n : null;
}
// end of SAST rating

// Reads the RECONCILED result, not the raw Python output.
//
// Before: this pulled ratings.management[] / ratings.performance[] straight from
// the Python service, and referenced a node that has since been deleted, so it
// threw on every run. Reading Python directly also threw away every bubble the
// reconciler recovered from Gemini.
const rec = $('reconcile ocr and omr1').first().json;

const ratings = rec.ratings ?? {};
const result = {};

// The reconciler emits a flat object, m1..m10 / p1..p10, where null means both
// engines agreed the row is genuinely blank. A blank stays null (stored as NULL,
// never 0): the database means skip NULLs, and a 0 would fail its CHECK (1..5).
let answered = 0;
let sum = 0;
for (let i = 1; i <= 10; i++) {
  for (const prefix of ['m', 'p']) {
    const key = `${prefix}${i}`;
    const score = rating(ratings[key]);
    result[key] = score;
    if (score !== null) { answered++; sum += score; }
  }
}

// Recomputed from the reconciled values, over the answered rows only (blanks
// are skipped, not counted as 0).
result.answered    = answered;
result.total_score = sum;
result.average     = answered ? Number((sum / answered).toFixed(2)) : null;
result.percent     = answered ? Number((sum / (answered * 5) * 100).toFixed(2)) : null;

result.grid_source = rec.grid_source ?? null;
result.table_found = rec.table_found ?? null;

// OCR text: Gemini-first, already decided by the reconciler.
result.cleaned_remarks = rec.remarks ?? '';

// Carried so the run data shows whether anything cross-checked this scan.
result.validation_status = rec.validation_status ?? 'auto';
result.review_reasons    = rec.review_reasons ?? [];

return [{ json: result }];

const link = $input.first().json.body.link;
const termId = $input.first().json.body.term_id;
const userId = $input.first().json.body.user_id;

const match = link.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
if (!match) throw new Error('Invalid Google Sheet URL');
const sheetId = match[1];

const gidMatch = link.match(/gid=([0-9]+)/);
const gid = gidMatch ? gidMatch[1] : '0';

const csvUrl = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv&gid=${gid}`;

// Added sheetId here so the next node can use {{$json.sheetId}}
return [{ json: { csvUrl, termId, userId, sheetId } }];

// Adds validation_status = auto (clean OCR/OMR result)
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    validation_status: 'auto'
  }
}));

// SAST rating, from website_src/rating.js
function rating(v) {
  if (typeof v === 'string') v = v.trim();
  else if (typeof v !== 'number') return null;
  if (v === '') return null;
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= 5 ? n : null;
}
// end of SAST rating

const body = $('sast-manual-correction1').first().json.body;
const instructorId = $('get instructor id7').first().json.instructor_id ?? null;
const subjectId    = $('get subject id6').first().json.subject_id ?? null;

// Safety: convert [null] arrays from Flutter → actual null
const termId  = Array.isArray(body.term_id)  ? null : (body.term_id  ?? null);
const userId  = Array.isArray(body.user_id)  ? null : (body.user_id  ?? null);
const taskId  = Array.isArray(body.task_id)  ? null : (body.task_id  ?? null);

const scores = {};
for (let i = 1; i <= 10; i++) {
  scores[`m${i}`] = rating(body[`m${i}`]);
  scores[`p${i}`] = rating(body[`p${i}`]);
}

return [{
  json: {
    raw: {
      instructor:              body.instructor ?? '',
      student_id:              body.student_id ?? '',
      Remarks_and_Suggestions: body.remarks    ?? '',
      submitted_date:          new Date().toISOString().split('T')[0],
      sao_staff_id:            userId,       // ← safe, no [null]
      term_id:                 termId,       // ← safe, no [null]
      instructor_ID:           instructorId,
      subject_id:              subjectId,
      task_id:                 taskId,       // ← safe, no [null]
      manually_corrected:      true,
      validation_status:       'corrected',
      ...scores,
    },
    instructor_ID:  instructorId,
    subject_id:     subjectId,
    term_id:        termId,
    failed_scan_id: body.failed_scan_id,
    scores,
  }
}];

