  buffer,
  `${taskId}.jpg`,
  'image/jpeg'
);

return {
  binary: { data: binaryData },
  json: {
    user_id    : userId,
    term_id    : termId,      // ← ADD
    task_id    : taskId,
    filename   : filename,    // ← ADD
    paper_size : paperSize,   // ← ADD
    timestamp  : timestamp,
  }
};

