// sast-manual-correction: the instructor / subject ids for 'get instructor id7' / 'get subject id6'.
// A valid id in the body (the website review page, the current app) is passed on as it is (the SQL
// still checks it). Without one (older app versions send only the typed names) the names are matched
// LOCALLY against 'Correction Candidates' with name_match.js: only a clear match gives an id; several
// close matches give no id AND no name for the SQL name lookup (it would just pick one), so the
// correction is refused with HTTP 422 and the candidates ('Correction Not Found'). No match keeps the
// typed text for the SQL lookup, as before. Nothing here is sent to Gemini.
// name matcher, from website_src/name_match.js
const NM_TOKEN_MIN = 0.55;       // weaker token pairs count as no match
const NM_KNOWN_RAW_MIN = 0.30;   // Gemini's pick from the subject list needs this much support from the raw reading
const NM_TITLES = new Set(['prof', 'professor', 'dr', 'doc', 'mr', 'mrs', 'ms', 'miss', 'madam', 'maam', 'sir', 'engr',
  'eng', 'atty', 'arch', 'rev', 'fr', 'hon', 'instr', 'instructor', 'teacher', 'phd', 'edd', 'dba', 'mba', 'mit', 'mat',
  'maed', 'lpt', 'rn', 'cpa', 'jr', 'sr', 'ii', 'iii', 'iv']);
const NM_STOP = new Set(['and', 'of', 'the', 'to', 'in', 'for', 'with', 'on', 'a', 'an', 'at']);
function nmFold(s) {
  return String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}
function nmNameTokens(s) {
  return nmFold(s).replace(/\bma['’‘`´]?am\b/g, ' maam ').replace(/[^a-z]+/g, ' ').split(' ')
    .filter((w) => w && !NM_TITLES.has(w));
}
function nmSubjectTokens(s) {
  return nmFold(s).replace(/[^a-z0-9]+/g, ' ').split(' ')
    .filter((w) => w && !NM_STOP.has(w) && !(/[a-z]/.test(w) && /[0-9]/.test(w)));
}
function nmAlnum(s) {
  return nmFold(s).replace(/[^a-z0-9]/g, '').toUpperCase();
}
function nmCodeKeys(s) {
  const up = nmFold(s).toUpperCase();
  const keys = new Set();
  for (const m of up.matchAll(/\b([A-Z]{2,8})[ .-]?([0-9]{1,4}[A-Z]?)\b/g)) keys.add(m[1] + m[2]);
  const whole = nmAlnum(s);
  if (/[A-Z]/.test(whole) && /[0-9]/.test(whole) && whole.length <= 12) keys.add(whole);
  return [...keys].filter((k) => k.length >= 3);
}
function nmEdit(a, b) {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
}
function nmTokenSim(want, got) {
  if (want === got) return 1;
  if (want.length === 1 || got.length === 1) return want[0] === got[0] ? 0.7 : 0;
  if (got.length >= 4 && want.startsWith(got)) return 0.85;   // abbreviation, e.g. prog / intro
  const r = 1 - nmEdit(want, got) / Math.max(want.length, got.length);
  return r >= NM_TOKEN_MIN ? r : 0;
}
function nmScore(wantToks, gotToks) {
  if (!wantToks.length || !gotToks.length) return { score: 0, cover: 0 };
  const w = (t) => (t.length === 1 ? 1 : t.length);
  const pairs = [];
  wantToks.forEach((a, i) => gotToks.forEach((b, j) => {
    const s = nmTokenSim(a, b);
    if (s > 0) pairs.push([s, i, j]);
  }));
  pairs.sort((x, y) => (y[0] - x[0]) || (x[1] - y[1]) || (x[2] - y[2]));
  const usedA = new Set();
  const usedB = new Set();
  let hitA = 0;
  let hitB = 0;
  for (const [s, i, j] of pairs) {
    if (usedA.has(i) || usedB.has(j)) continue;
    usedA.add(i);
    usedB.add(j);
    hitA += s * w(wantToks[i]);
    hitB += s * w(gotToks[j]);
  }
  const sum = (ts) => ts.reduce((t, x) => t + w(x), 0);
  const cover = hitA / sum(wantToks);
  const score = 0.75 * cover + 0.25 * (hitB / sum(gotToks));
  return { score: Math.round(score * 10000) / 10000, cover: Math.round(cover * 10000) / 10000 };
}
function nmSubjectFit(code, name, text) {
  const key = nmAlnum(code);
  const keys = nmCodeKeys(text);
  const exact = key !== '' && (keys.includes(key) || nmAlnum(text) === key);
  const fuzzy = !exact && key.length >= 4 && keys.some((k) => k.length >= 4 && nmEdit(k, key) <= 1);
  const title = nmScore(nmSubjectTokens(name), nmSubjectTokens(text));
  return { exact, fuzzy, name_score: title.score, name_cover: title.cover };
}
function nmList(v) {
  if (Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v ?? '')); return Array.isArray(p) ? p : []; } catch (e) { return []; }
}
function nmBestInstructor(raw, names, minScore, margin) {
  const got = nmNameTokens(raw);
  const scored = !got.length ? [] : nmList(names)
    .map((n) => String(n ?? '').trim())
    .filter(Boolean)
    .map((name) => ({ name, score: nmScore(nmNameTokens(name), got).score }))
    .filter((c) => c.score >= minScore - 1e-6)
    .sort((a, b) => (b.score - a.score) || a.name.localeCompare(b.name));
  if (!scored.length) return { match: 'none', name: '', score: null, contenders: [] };
  const close = scored.filter((c) => scored[0].score - c.score < margin - 1e-6);
  if (close.length > 1) return { match: 'ambiguous', name: '', score: scored[0].score, contenders: close.map((c) => c.name) };
  return { match: 'found', name: scored[0].name, score: scored[0].score, contenders: [] };
}
function nmKnownSubject(known, subjects, raw) {
  const key = nmAlnum(known);
  if (!key) return '';
  const hit = nmList(subjects).find((s) => s && nmAlnum(s.code) === key);
  if (!hit) return '';
  const fit = nmSubjectFit(hit.code, hit.name, raw);
  return fit.exact || fit.fuzzy || fit.name_score >= NM_KNOWN_RAW_MIN - 1e-6 ? String(hit.code) : '';
}
// end of name matcher

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const INSTRUCTOR_MATCH_MIN    = 0.70;   // same as the phone reconciler / Website Decide
const INSTRUCTOR_MATCH_MARGIN = 0.10;
const SUBJECT_MATCH_MIN       = 0.60;   // title score (a code hit is exact)
const SUBJECT_NAME_COVER      = 0.75;   // share of the subject title the text must show
const SUBJECT_MATCH_MARGIN    = 0.10;
const MAX_CANDIDATES          = 5;
const CANDIDATE_MIN_SCORE     = 0.30;
const EPS = 1e-6;

function cmText(v) {
  return (typeof v === 'string' || typeof v === 'number') ? String(v).trim() : '';
}
function cmId(v) {
  const s = cmText(v).toLowerCase();
  return UUID_RE.test(s) ? s : '';
}
const r2 = (x) => (typeof x === 'number' ? Math.round(x * 100) / 100 : null);

let body = {};
try { body = $('sast-manual-correction1').first().json.body || {}; } catch (e) {}
let cands = null;   // null = the candidate lookup failed: the SQL lookups run on the body as before
try {
  const c = $('Correction Candidates').first().json || {};
  if (Number(c.candidates_version) === 1) cands = c;
} catch (e) {}

const instructors = cands ? nmList(cands.instructors)
  .filter((x) => x && UUID_RE.test(String(x.id || '').toLowerCase()) && String(x.name || '').trim())
  .map((x) => ({ id: String(x.id).toLowerCase(), name: String(x.name).trim() })) : null;
const subjects = cands ? nmList(cands.subjects)
  .filter((x) => x && UUID_RE.test(String(x.id || '').toLowerCase()) && (String(x.code || '').trim() || String(x.name || '').trim()))
  .map((x) => ({ id: String(x.id).toLowerCase(), code: String(x.code || '').trim(), name: String(x.name || '').trim() })) : null;

// ---- instructor
function matchInstructor() {
  const raw = cmText(body.instructor);
  const id = cmId(body.instructor_id);
  if (id) return { match: 'id', id, sqlName: raw, score: null, candidates: [] };
  if (!raw) return { match: 'missing', id: '', sqlName: '', score: null, candidates: [] };
  if (!instructors) return { match: 'unavailable', id: '', sqlName: raw, score: null, candidates: [] };
  const best = nmBestInstructor(raw, instructors.map((x) => x.name), INSTRUCTOR_MATCH_MIN, INSTRUCTOR_MATCH_MARGIN);
  const got = nmNameTokens(raw);
  const scored = instructors
    .map((x) => ({ ...x, score: nmScore(nmNameTokens(x.name), got).score }))
    .sort((a, b) => (b.score - a.score) || a.name.localeCompare(b.name) || a.id.localeCompare(b.id));
  if (best.match === 'found') {
    const hits = instructors.filter((x) => x.name === best.name);
    if (hits.length === 1) return { match: 'found', id: hits[0].id, sqlName: raw, score: r2(best.score), candidates: [] };
  }
  if (best.match === 'ambiguous' || best.match === 'found') {
    const names = new Set(best.match === 'found' ? [best.name] : best.contenders);
    const close = scored.filter((x) => names.has(x.name)).slice(0, MAX_CANDIDATES)
      .map((x) => ({ id: x.id, name: x.name, score: r2(x.score) }));
    return { match: 'ambiguous', id: '', sqlName: '', score: r2(best.score), candidates: close };
  }
  const shown = scored.filter((x) => x.score >= CANDIDATE_MIN_SCORE - EPS).slice(0, MAX_CANDIDATES)
    .map((x) => ({ id: x.id, name: x.name, score: r2(x.score) }));
  return { match: 'none', id: '', sqlName: raw, score: null, candidates: shown };
}

// ---- subject (code on the text first, then the title)
function matchSubject() {
  const raw = cmText(body.subject);
  const id = cmId(body.subject_id);
  if (id) return { match: 'id', id, sqlText: raw, score: null, candidates: [] };
  if (!raw) return { match: 'missing', id: '', sqlText: '', score: null, candidates: [] };
  if (!subjects) return { match: 'unavailable', id: '', sqlText: raw, score: null, candidates: [] };
  const all = subjects.map((s) => {
    const fit = nmSubjectFit(s.code, s.name, raw);
    const score = fit.exact ? 1 : Math.max(fit.fuzzy ? 0.9 : 0, fit.name_score);
    return { ...s, exact: fit.exact, fuzzy: fit.fuzzy, cover: fit.name_cover, title: fit.name_score, score };
  }).sort((a, b) => (Number(b.exact) - Number(a.exact)) || (b.score - a.score) || a.code.localeCompare(b.code)
    || a.id.localeCompare(b.id));
  const out = (x) => ({ id: x.id, code: x.code, name: x.name, score: r2(x.score) });
  const exact = all.filter((x) => x.exact);
  if (exact.length === 1) return { match: 'found', id: exact[0].id, sqlText: raw, score: 1, candidates: [] };
  if (exact.length > 1) {
    return { match: 'ambiguous', id: '', sqlText: '', score: 1, candidates: exact.slice(0, MAX_CANDIDATES).map(out) };
  }
  // a course code on the text that is no subject: never pick a subject by its title instead
  const unknownCode = nmCodeKeys(raw).some((k) => /[A-Z]/.test(k) && /[0-9]{2}/.test(k));
  const strong = unknownCode ? [] : all.filter((x) => x.title >= SUBJECT_MATCH_MIN - EPS && x.cover >= SUBJECT_NAME_COVER - EPS)
    .sort((a, b) => b.title - a.title);
  if (strong.length === 1 || (strong.length > 1 && strong[0].title - strong[1].title >= SUBJECT_MATCH_MARGIN - EPS)) {
    return { match: 'found', id: strong[0].id, sqlText: raw, score: r2(strong[0].title), candidates: [] };
  }
  if (strong.length > 1) {
    const close = strong.filter((x) => strong[0].title - x.title < SUBJECT_MATCH_MARGIN - EPS);
    return { match: 'ambiguous', id: '', sqlText: '', score: r2(strong[0].title), candidates: close.slice(0, MAX_CANDIDATES).map(out) };
  }
  const shown = all.filter((x) => x.fuzzy || x.score >= CANDIDATE_MIN_SCORE - EPS).slice(0, MAX_CANDIDATES).map(out);
  return { match: 'none', id: '', sqlText: raw, score: null, candidates: shown };
}

const instr = matchInstructor();
const subj = matchSubject();

return [{
  json: {
    correction_match_version: 1,
    instructor_id: instr.id,          // -> get instructor id7 $2 ('' = none)
    instructor_name: instr.sqlName,   // -> get instructor id7 $1 ('' = no name lookup)
    subject_id: subj.id,              // -> get subject id6 $3
    subject_text: subj.sqlText,       // -> get subject id6 $2
    instructor_match: { match: instr.match, score: instr.score, candidates: instr.candidates },
    subject_match: { match: subj.match, score: subj.score, candidates: subj.candidates },
  },
}];

// sast-manual-correction: the instructor or subject did not resolve to one database entry. Answered
// HTTP 422 by 'Correction Not Found Response'; nothing is saved, the failed_scan_queue row is NOT
// marked validated and no import_errors row is made, so the scan stays pending in the app and the
// staff member picks the instructor / subject from the list. Input: the 'Map target' item.
const m = $input.first()?.json ?? {};
let body = {};
try { body = $('sast-manual-correction1').first().json.body || {}; } catch (e) {}
let match = {};
try { match = $('Correction Name Match').first().json || {}; } catch (e) {}

const has = (v) => typeof v === 'string' ? v.trim() !== '' : (v !== null && v !== undefined && v !== '');
const noInstructor = !has(m.instructor_ID);
const noSubject = !has(m.true_subject_id);
const text = (v) => (typeof v === 'string' || typeof v === 'number') ? String(v).trim() : '';
const shown = (v) => (v.length > 80 ? v.slice(0, 77) + '...' : v);

function list(v) {
  return Array.isArray(v) ? v.filter((x) => x && typeof x === 'object' && x.id).slice(0, 5) : [];
}
function part(kind, raw, info) {
  const what = kind === 'instructor' ? 'instructor' : 'subject';
  const m2 = info && typeof info === 'object' ? info.match : null;
  if (!raw) return `No ${what} was given.`;
  if (m2 === 'ambiguous') return `Several ${what === 'instructor' ? 'instructors' : 'subjects'} fit "${shown(raw)}".`;
  if (m2 === 'id') return `The selected ${what} can no longer be credited.`;
  return `The ${what} "${shown(raw)}" was not found.`;
}

const iInfo = match.instructor_match || {};
const sInfo = match.subject_match || {};
const code = noInstructor && noSubject ? 'instructor_and_subject_not_found'
  : (noInstructor ? 'instructor_not_found' : 'subject_not_found');
const parts = [];
if (noInstructor) parts.push(part('instructor', text(body.instructor), iInfo));
if (noSubject) parts.push(part('subject', text(body.subject), sInfo));
const pick = noInstructor && noSubject ? 'the instructor and the subject' : (noInstructor ? 'the instructor' : 'the subject');
const message = `Not saved: ${parts.join(' ')} Pick ${pick} from the list and submit again.`;

const candidates = {};
if (noInstructor) {
  candidates.instructors = list(iInfo.candidates).map((c) => ({ id: String(c.id), name: String(c.name || '') }));
}
if (noSubject) {
  candidates.subjects = list(sInfo.candidates).map((c) => ({ id: String(c.id), code: String(c.code || ''), name: String(c.name || '') }));
}

return [{
  json: {
    response_code: 422,
    response: {
      success: false,
      code,
      message,
      instructor_match: noInstructor ? (iInfo.match || 'none') : 'found',
      subject_match: noSubject ? (sInfo.match || 'none') : 'found',
      candidates,
      failed_scan_id: body.failed_scan_id ?? null,
    },
  },
}];
